class ContaBancaria:
    def __init__(self, saldo=0):
        self.saldo = saldo

    def depositar(self, valor):
        self.saldo += valor

    def sacar(self, valor):
        if valor > self.saldo:
            raise ValueError("Saldo insuficiente")
        self.saldo -= valor

    def extrato(self):
        return self.saldo

conta = ContaBancaria(50)
conta.depositar(50)
conta.sacar(30)
print(conta.extrato())

